export const keyActions=[['forward','앞으로','KeyW'],['back','뒤로','KeyS'],['left','왼쪽','KeyA'],['right','오른쪽','KeyD'],['jump','점프','Space'],['sprint','달리기','ShiftLeft'],['crouch','앉기 / 슬라이드','KeyC'],['reload','재장전','KeyR'],['meleeAbility','근접 특수 능력','KeyE'],['melee','빠른 근접','KeyF'],['view','시점 전환','KeyV'],['primary','주무기','Digit1'],['sidearm','보조무기','Digit2'],['blade','근접무기','Digit3'],['cycle','다음 무기','KeyQ'],['arsenal','무기고','KeyB'],['refill','연습 탄약 보충','KeyT']];
export const touchControls=[['joystick','이동',.17,.72,112],['touchFire','발사',.86,.57,76],['touchAim','조준',.90,.36,56],['touchJump','점프 / 슬라이드',.86,.79,68],['touchCrouch','앉기',.61,.81,50],['touchReload','장전',.71,.58,54],['touchMelee','근접',.61,.62,50],['touchMeleeAbility','특수 능력',.77,.36,52],['touchWeapon','무기',.59,.40,50]];
const keyDefaults=()=>Object.fromEntries(keyActions.map(([id,,code])=>[id,code]));
const validCode=code=>/^(Key[A-Z]|Digit[0-9]|Numpad[0-9]|Space|ShiftLeft|ShiftRight|ControlLeft|ControlRight|Arrow(?:Up|Down|Left|Right)|Backquote|Minus|Equal|BracketLeft|BracketRight|Backslash|Semicolon|Quote|Comma|Period|Slash|CapsLock|Enter|Backspace)$/.test(code);
export function keyLabel(code){return ({Space:'SPACE',ShiftLeft:'왼쪽 SHIFT',ShiftRight:'오른쪽 SHIFT',ControlLeft:'왼쪽 CTRL',ControlRight:'오른쪽 CTRL',ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→',Backquote:'`',Minus:'-',Equal:'=',BracketLeft:'[',BracketRight:']',Backslash:'\\',Semicolon:';',Quote:"'",Comma:',',Period:'.',Slash:'/',CapsLock:'CAPS',Enter:'ENTER',Backspace:'⌫'})[code]||code.replace(/^Key|^Digit/,'').replace('Numpad','NUM ')}
export function rebind(bindings,action,code){if(!keyActions.some(([id])=>id===action)||!validCode(code))return null;const next={...bindings},old=next[action],other=keyActions.find(([id])=>id!==action&&next[id]===code)?.[0];if(other)next[other]=old;next[action]=code;return next}
export function normalizeBindings(input={}){input=input&&typeof input==='object'?input:{};let result=keyDefaults();for(const[id]of keyActions){if(validCode(input[id]||''))result=rebind(result,id,input[id])}return result}
export function canonicalKey(bindings,code){if(code==='Escape')return code;const entry=keyActions.find(([id])=>bindings[id]===code);if(entry)return entry[2];if(code==='ShiftRight'&&bindings.sprint==='ShiftLeft')return 'ShiftLeft';if((code==='ControlLeft'||code==='ControlRight')&&bindings.crouch==='KeyC')return 'ControlLeft';return ''}
export function touchRect(value,definition,width,height){
 const [id,,dx,dy,ds]=definition,v=value||{},large=id==='joystick';const limit=Math.max(32,Math.min(width,height)-16),size=Math.min(limit,Math.max(large?84:44,Math.min(large?180:140,Number.isFinite(v.size)?v.size:ds)));
 const clamp=(n,min,max)=>Math.min(max,Math.max(min,n)),mx=(size/2+4)/Math.max(1,width),my=(size/2+4)/Math.max(1,height);
 return{x:clamp(Number.isFinite(v.x)?v.x:dx,mx,1-mx),y:clamp(Number.isFinite(v.y)?v.y:dy,my,1-my),size};
}
export function createControlSettings({onChange=()=>{}}={}){
 const $=id=>document.getElementById(id);let saved={};try{saved=JSON.parse(localStorage.getItem('vector.controls.v1'))||{}}catch{}
 let config={keys:normalizeBindings(saved.keys),touch:{landscape:saved.touch?.landscape||{},portrait:saved.touch?.portrait||{}}},capture=null,selected='touchFire',tab='keyboard',drag=null;
 const orientation=()=>innerWidth>=innerHeight?'landscape':'portrait';
 const root=document.createElement('div');root.id='controlsOverlay';root.className='modal-overlay controls-overlay';root.hidden=true;
 root.innerHTML='<section class="controls-card"><div class="controls-heading"><div><div class="eyebrow">YOUR CONTROLS</div><h2>조작 설정</h2></div><button id="controlsDone" class="secondary">완료 ✓</button></div><div class="controls-tabs"><button id="keyboardTab" class="active">PC 단축키</button><button id="mobileTab">모바일 버튼 배치</button></div><p id="controlsNote" role="status" aria-live="polite">변경 사항은 이 기기에 자동 저장됩니다.</p><div id="keyboardPanel"><div id="keyBindingGrid"></div><p class="controls-help">버튼을 누른 뒤 새 키를 입력하세요. 겹치는 키는 서로 교환합니다.<br>ESC는 취소·일시정지로 고정됩니다. 마우스 왼쪽 발사·오른쪽 조준은 유지됩니다.</p><button id="resetKeys" class="secondary">기본 키로 초기화</button></div><div id="mobilePanel" hidden><p class="controls-help">버튼을 끌어 위치를 옮기고 선택한 버튼의 크기를 조절하세요. 점프 버튼은 탭으로 점프, 길게 눌러 슬라이드합니다.<br><span id="layoutOrientation"></span> · 다른 방향은 화면을 돌려 편집할 수 있습니다.</p><div id="touchLayoutPreview"></div><label class="touch-size-label"><span id="touchSelectedLabel">발사 크기</span><output id="touchSizeOut"></output><input id="touchSize" type="range" min="44" max="140" step="2"></label><button id="resetTouch" class="secondary">현재 방향 배치 초기화</button></div></section>';
 document.body.append(root);
 const note=text=>$('controlsNote').textContent=text;
 function save(){try{localStorage.setItem('vector.controls.v1',JSON.stringify(config));note('이 기기에 저장했어요.')}catch{note('브라우저 저장 공간을 사용할 수 없어 이번 실행에만 적용돼요.')}onChange();applyTouch()}
 function renderKeys(){const grid=$('keyBindingGrid');grid.replaceChildren();for(const[id,label]of keyActions){const row=document.createElement('label');row.className='key-binding';const title=document.createElement('span');title.textContent=label;const button=document.createElement('button');button.type='button';button.textContent=keyLabel(config.keys[id]);button.setAttribute('aria-label',label+' 단축키 변경');button.onclick=()=>{capture=id;renderKeys();note(label+'에 사용할 키를 누르세요. ESC로 취소합니다.')};if(capture===id){button.textContent='키 입력…';button.className='recording'}row.append(title,button);grid.append(row)}}
 function applyTouch(){const area=$('touchUi');if(!area)return;const bounds=area.getBoundingClientRect(),w=bounds.width||innerWidth,h=bounds.height||innerHeight;for(const def of touchControls){const el=$(def[0]);if(!el)continue;const p=touchRect(config.touch[orientation()][def[0]],def,w,h);Object.assign(el.style,{position:'absolute',left:p.x*100+'%',top:p.y*100+'%',width:p.size+'px',height:p.size+'px',right:'auto',bottom:'auto',transform:'translate(-50%,-50%)'})}}
 function layoutSize(){const el=$('touchLayoutPreview');const ratio=innerWidth/innerHeight;el.style.width=Math.min(660,innerWidth-64,innerHeight*.48*ratio)+'px';el.style.aspectRatio=String(ratio);return{width:innerWidth,height:innerHeight,scale:el.getBoundingClientRect().width/innerWidth}}
 function renderTouch(){if(tab!=='mobile'||root.hidden)return;const box=$('touchLayoutPreview');box.replaceChildren();const dims=layoutSize();$('layoutOrientation').textContent=orientation()==='landscape'?'가로 화면 배치':'세로 화면 배치';for(const def of touchControls){const[id,label]=def,p=touchRect(config.touch[orientation()][id],def,dims.width,dims.height),b=document.createElement('button');b.type='button';b.dataset.control=id;b.textContent=label;b.className='layout-button'+(id===selected?' selected':'');b.setAttribute('aria-label',label+' 위치 조절');Object.assign(b.style,{left:p.x*100+'%',top:p.y*100+'%',width:p.size*dims.scale+'px',height:p.size*dims.scale+'px'});b.onpointerdown=e=>{e.preventDefault();selected=id;drag={id,pointer:e.pointerId,x:e.clientX,y:e.clientY,start:p};b.setPointerCapture(e.pointerId);box.querySelectorAll('button').forEach(n=>n.classList.toggle('selected',n===b));updateSize()};b.onpointermove=e=>{if(!drag||drag.id!==id||e.pointerId!==drag.pointer)return;const r=box.getBoundingClientRect(),next=touchRect({...p,x:drag.start.x+(e.clientX-drag.x)/r.width,y:drag.start.y+(e.clientY-drag.y)/r.height},def,dims.width,dims.height);config.touch[orientation()][id]=next;b.style.left=next.x*100+'%';b.style.top=next.y*100+'%'};const end=e=>{if(!drag||drag.pointer!==e.pointerId)return;drag=null;save()};b.onpointerup=end;b.onpointercancel=end;b.onlostpointercapture=end;b.onkeydown=e=>{const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.code];if(!delta)return;e.preventDefault();const cur=touchRect(config.touch[orientation()][id],def,dims.width,dims.height);config.touch[orientation()][id]=touchRect({...cur,x:cur.x+delta[0]*.015,y:cur.y+delta[1]*.015},def,dims.width,dims.height);save();renderTouch();box.querySelector('[data-control="'+id+'"]').focus()};box.append(b)}updateSize()}
 function updateSize(){const def=touchControls.find(([id])=>id===selected),p=touchRect(config.touch[orientation()][selected],def,innerWidth,innerHeight);$('touchSelectedLabel').textContent=def[1]+' 크기';$('touchSize').min=selected==='joystick'?84:44;$('touchSize').max=selected==='joystick'?180:140;$('touchSize').value=p.size;$('touchSizeOut').textContent=Math.round(p.size)+'px'}
 function switchTab(next){capture=null;tab=next;$('keyboardPanel').hidden=next!=='keyboard';$('mobilePanel').hidden=next!=='mobile';$('keyboardTab').classList.toggle('active',next==='keyboard');$('mobileTab').classList.toggle('active',next==='mobile');renderKeys();renderTouch()}
 function close(){root.hidden=true;capture=null;drag=null;onChange();$('controlsSettings')?.focus()}
 $('keyboardTab').onclick=()=>switchTab('keyboard');$('mobileTab').onclick=()=>switchTab('mobile');$('controlsDone').onclick=close;$('resetKeys').onclick=()=>{config.keys=keyDefaults();capture=null;save();renderKeys()};$('resetTouch').onclick=()=>{config.touch[orientation()]={};save();renderTouch()};$('touchSize').oninput=e=>{const def=touchControls.find(([id])=>id===selected),cur=touchRect(config.touch[orientation()][selected],def,innerWidth,innerHeight);config.touch[orientation()][selected]={...cur,size:+e.target.value};save();renderTouch()};
 document.addEventListener('keydown',e=>{if(root.hidden)return;if(capture){e.preventDefault();e.stopImmediatePropagation();if(e.code==='Escape'){capture=null;renderKeys();note('키 변경을 취소했어요.');return}if(e.metaKey||e.altKey||e.ctrlKey&&!/^Control/.test(e.code)){note('다른 보조 키를 놓고 한 키만 입력하세요.');return}const next=rebind(config.keys,capture,e.code);if(!next){note('이 키는 브라우저에서 사용합니다. 다른 키를 선택하세요.');return}config.keys=next;capture=null;save();renderKeys();return}if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return}if(e.code==='Tab'){const nodes=[...root.querySelectorAll('button,input')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},true);
 window.addEventListener('resize',()=>{drag=null;applyTouch();renderTouch()});applyTouch();
 return{canonical:code=>canonicalKey(config.keys,code),label:action=>keyLabel(config.keys[action]),applyTouch,open(next='keyboard'){onChange();root.hidden=false;switchTab(next);$('controlsDone').focus()}};
}
